'use strict';
const X=Expedition,$=id=>document.getElementById(id),KEY='kq-expedition-v2';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let stored=null;try{stored=X.restore(localStorage.getItem(KEY));}catch{}
let state=stored||X.fresh(newSeed()),task=null,view='map',zoom=1,panX=0,panY=0,drag=null,suppressUntil=0,toastTimer,hintTimer,returnFocus=null,saveWarning=false;
const positions=[[10,66],[24.5,35],[37.5,67],[50.5,29],[63,58],[74,28],[84.5,65],[91.5,29]],mobilePositions=[[22,20],[68,20],[28,40],[76,40],[22,60],[68,60],[30,79],[80,79]];
const asset=id=>'assets/'+id+'.webp';
const thumb=id=>'assets/'+id+'-thumb.webp';
const badgeNames=[['范围之印','现行之印','审核之印'],['预测之星','客服之星','检测之星','分类之星'],['知识接口','权限开关','复核之灯','成本筹码'],['基线水晶','测试水晶','质量水晶','复核水晶'],['投入账页','持续账页','工时账页','收益账页'],['时间之证','来源之证','审核之证','授权之证'],['权限星盘','监督星盘','监测星盘','回退星盘'],['目标星章','数据星章','价值星章','治理星章']];
const walker=`<svg class="walker-svg" viewBox="0 0 40 60"><ellipse cx="20" cy="57" rx="10" ry="2.5" fill="#223b27" opacity=".2"/><path class="leg" d="M16 42L14 55" stroke="#4a3e2e" stroke-width="5" stroke-linecap="round"/><path class="leg two" d="M23 42L26 55" stroke="#4a3e2e" stroke-width="5" stroke-linecap="round"/><g class="body"><path d="M12 24Q20 18 28 25L31 44Q20 49 9 44Z" fill="#56735a" stroke="#344f3c"/><path d="M25 26L30 28L30 40L25 41Z" fill="#a48c5b"/><circle cx="20" cy="17" r="8" fill="#dfbf8a"/><path d="M10 17Q9 2 22 3L29 17Z" fill="#6d7e52"/><path d="M9 17L31 17" stroke="#3d5839" stroke-width="3" stroke-linecap="round"/><path d="M15 27L11 36M25 27L29 35" stroke="#dfbf8a" stroke-width="4" stroke-linecap="round"/><path d="M12 26L22 44" stroke="#bca36e" stroke-width="2"/></g></svg>`;
function newSeed(){const a=new Uint32Array(1);if(globalThis.crypto?.getRandomValues){crypto.getRandomValues(a);return a[0];}return Date.now()>>>0;}
function day(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!saveWarning){saveWarning=true;toast('浏览器未允许保存；关闭页面后可能丢失本次进度。');}}}
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function modal(html,wide=false){returnFocus=document.activeElement;$('dialogBody').innerHTML=html;$('dialog').classList.toggle('wide',wide);if(!$('dialog').open)$('dialog').showModal();$('dialog').scrollTop=0;}
function close(){if($('dialog').open)$('dialog').close();if(returnFocus?.isConnected)returnFocus.focus();else $(view==='map'?'continueJourney':'viewport').focus();}
$('close').onclick=close;
function stars(n,max=3){return '★'.repeat(n)+'☆'.repeat(max-n);}
function totals(){$('navStars').textContent=state.best.reduce((a,b)=>a+b,0);$('navCollection').textContent=state.collections.length;}
function nextIndex(){if(!X.run(state).finished)return state.current;return Math.min(7,state.best.findIndex(x=>!x)<0?7:state.best.findIndex(x=>!x));}
function positionNodes(){const mobile=window.innerWidth<=760;document.querySelectorAll('[data-node]').forEach(el=>{const p=(mobile?mobilePositions:positions)[+el.dataset.node];el.style.left=p[0]+'%';el.style.top=p[1]+'%';});const p=(mobile?mobilePositions:positions)[nextIndex()];$('mapWalker').style.left=(p[0]-6)+'%';$('mapWalker').style.top=(p[1]+5)+'%';}
function renderMap(){totals();const done=state.best.filter(Boolean).length,current=nextIndex();$('journeyProgress').textContent=`${done} / 8 站已点亮`;$('personalRecord').textContent=done===8?'群岛已全部点亮。重访风景，补齐三星，收藏依然保留。':`已收藏 ${state.collections.length} / 31 枚知识纪念物 · 探索 ${state.days.length} 天`;$('continueJourney').textContent=done===8?'重访终点站 →':`继续第 ${current+1} 站 →`;
 $('mapNodes').innerHTML=X.levels.map((l,i)=>`<button class="map-node ${!X.unlocked(state,i)?'locked':''} ${i===current?'current':''}" data-node="${i}" aria-label="第${i+1}站，${l.name}，${!X.unlocked(state,i)?'尚未解锁':state.best[i]?'已获得'+state.best[i]+'星':'可以探索'}"><span class="node-circle"><img src="${thumb(l.id)}" alt=""><span class="node-number">${X.unlocked(state,i)?i+1:'锁'}</span></span><span class="node-label">${l.name}</span><span class="node-stars">${state.best[i]?stars(state.best[i]):X.unlocked(state,i)?'待点亮':'···'}</span></button>`).join('');
 $('levelCards').innerHTML=X.levels.map((l,i)=>`<button class="level-card ${X.unlocked(state,i)?'':'locked'}" data-level="${i}"><img src="${thumb(l.id)}" alt=""><span class="card-copy"><small>第 ${String(i+1).padStart(2,'0')} 站 · ${l.kind==='multi'?'十选四':l.kind==='combine'?'物件组合':'证据筛选'}</small><strong>${l.name}</strong><span class="stars">${state.best[i]?stars(state.best[i]):X.unlocked(state,i)?'出发探索 →':'前一站通关后解锁'}</span></span></button>`).join('');
 document.querySelectorAll('[data-node]').forEach(el=>el.onclick=()=>enter(+el.dataset.node));document.querySelectorAll('[data-level]').forEach(el=>el.onclick=()=>enter(+el.dataset.level));$('mapWalker').innerHTML=walker;positionNodes();save();}
function showMap(){close();exitImmersive();view='map';$('mapView').hidden=false;$('playView').hidden=true;clearTimeout(hintTimer);renderMap();$('continueJourney').focus();}
$('mapButton').onclick=showMap;$('backMap').onclick=showMap;$('continueJourney').onclick=()=>enter(nextIndex());
function enter(index,replay=false){if(!X.unlocked(state,index)){toast('先完成前一站，就能点亮通向这里的路。');return;}
 if(state.runs[index]?.finished&&!replay){modal(`<span class="eyebrow">重访第 ${index+1} 站</span><h2 id="dialogTitle">${X.levels[index].name}</h2><div class="big-stars">${stars(state.best[index])}</div><p>最佳星级和收藏会一直保留。再次探索只重置这一关的线索，争取用更少的提示完成它。</p><div class="actions"><button id="cancelReplay">先看看地图</button><button id="startReplay" class="primary">再次探索本关</button></div>`);$('cancelReplay').onclick=close;$('startReplay').onclick=()=>enter(index,true);return;}
 close();X.open(state,index,replay);task=X.scene(index,state.seed);view='play';$('mapView').hidden=true;$('playView').hidden=false;$('sceneMessage').textContent='';$('panelFeedback').innerHTML='';resetView();renderScene();if(!state.guide){help(true);}else $('viewport').focus();save();}
function run(){return X.run(state);}
function renderScene(){task=X.scene(state.current,state.seed);const r=run();totals();$('chapter').textContent=`第 ${String(state.current+1).padStart(2,'0')} / 08 站 · ${task.theme}`;$('title').textContent=task.name;$('request').textContent=task.request;$('count').textContent=`${r.accepted.length} / ${task.target}`;$('location').textContent=task.kind==='multi'?'卷页寻踪 · 找到十份，选四份':task.kind==='combine'?'缺页卷轴 · 拖入或点选物件':'场景寻物 · 读懂再收集';$('art').src=asset(task.id);$('art').alt=task.name+'的完整寻物场景';
 $('objects').innerHTML=task.items.map(item=>`<button class="hotspot ${r.accepted.includes(item.id)?'found':r.chosen.includes(item.id)?'chosen':r.seen.includes(item.id)?'seen':''}" data-item="${item.id}" style="left:${item.x}%;top:${item.y}%;width:${item.w}%;height:${item.h}%" aria-label="查看${esc(item.name)}${r.accepted.includes(item.id)?'，已收集':''}" ${task.kind==='combine'&&!r.accepted.includes(item.id)?'draggable="true"':''}></button>`).join('');
 document.querySelectorAll('[data-item]').forEach(el=>{el.onclick=()=>{if(Date.now()<suppressUntil)return;inspect(el.dataset.item);};if(task.kind==='combine'){el.ondragstart=e=>{if(zoom>1&&drag?.moved){e.preventDefault();return;}e.dataTransfer.setData('text/plain',el.dataset.item);e.dataTransfer.effectAllowed='copy';const item=task.items.find(x=>x.id===el.dataset.item),ghost=$('dragGhost');ghost.style.backgroundImage="url('"+asset(task.id)+"')";ghost.style.backgroundSize='1000% 1000%';ghost.style.backgroundPosition=item.x+'% '+item.y+'%';e.dataTransfer.setDragImage?.(ghost,38,38);$('dropSlot')?.classList.add('dragover');};el.ondragend=()=>$('dropSlot')?.classList.remove('dragover');}});$('sceneWalker').innerHTML=walker;const path=[[31,66,89],[62,76,64],[33,72,83],[26,73,87],[39,54,69],[27,36,88],[43,61,90],[45,59,68]][state.current];$('sceneWalker').style.setProperty('--walk-a',path[0]+'%');$('sceneWalker').style.setProperty('--walk-b',path[1]+'%');$('sceneWalker').style.setProperty('--walk-y',path[2]+'%');renderPanel();save();}
function renderPanel(){const r=run();if(task.kind==='select'){$('taskPanel').innerHTML=`<span class="eyebrow">证据筛选</span><h2>先找到，再判断。</h2><p>${esc(task.story)}</p><p>线索藏在画面中的实物上。点击书、信件、仪器或器具，查看它留下的内容。</p>${Array.from({length:task.target},(_,i)=>`<div class="target-line ${i<r.accepted.length?'done':''}"><span class="dot">${i<r.accepted.length?'✓':i+1}</span><span>${i<r.accepted.length?esc(task.items.find(x=>x.id===r.accepted[i]).text):'等待一份有效证据'}</span></div>`).join('')}`;
 }else if(task.kind==='multi'){$('taskPanel').innerHTML=`<span class="eyebrow">十份卷页 · 四份答案</span><h2>收集候选，统一核验。</h2><p>${esc(task.story)}</p><p>已发现 ${r.seen.length} / 10 份 · 已选 ${r.chosen.length} / 4 份。下方只显示打开过的卷轴；点击可重读和更换候选。</p><div class="clue-list">${r.seen.map(id=>{const x=task.items.find(x=>x.id===id);return `<button class="clue-button ${r.chosen.includes(id)?'selected':''}" data-clue="${id}">${r.chosen.includes(id)?'✓ ':''}${esc(x.name)}<small>${esc(x.text)}</small></button>`;}).join('')||'<p>先到场景里找一份卷轴。</p>'}</div><button id="verify" ${r.chosen.length===4?'':'disabled'}>核验这四份候选</button>`;document.querySelectorAll('[data-clue]').forEach(el=>el.onclick=()=>inspect(el.dataset.clue));$('verify').onclick=()=>{const result=X.verify(state);if(!result.ok){feedback(result.message,false);toast('还有提案不合适，可以重读并替换候选。');}else{feedback('四项用途均符合本次委托，证据已经整理完成。',true);toast('四份卷轴核验通过！');}renderScene();};
 }else{const recipe=task.recipes[r.active];$('taskPanel').innerHTML=`<span class="eyebrow">物件组合 · ${r.solved.length} / 4 已合拢</span><h2>为卷轴补上缺口。</h2><div class="recipe-tabs">${task.recipes.map((p,i)=>`<button data-recipe="${i}" class="${i===r.active?'active':''} ${r.solved.includes(i)?'done':''}">${r.solved.includes(i)?'✓ ':''}${esc(p[0])}</button>`).join('')}</div><div class="parchment"><h3>${esc(recipe[0])}</h3><p>${esc(recipe[1])}</p><div id="dropSlot" class="drop-slot ${r.solved.includes(r.active)?'solved':''}" tabindex="0" role="region" aria-label="卷轴物件缺口，可把场景物件拖入，也可点击物件后放入">${r.solved.includes(r.active)?'✓ 卷轴已经合拢':'把场景中的对应物件拖到这里<br>或点开物件，再选择「放入卷轴」'}</div></div><p>物件就在画面里。不同卷轴需要不同的能力，先读提示再选。</p>`;document.querySelectorAll('[data-recipe]').forEach(el=>el.onclick=()=>{r.active=+el.dataset.recipe;renderPanel();save();});const slot=$('dropSlot');slot.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';slot.classList.add('dragover');};slot.ondragleave=()=>slot.classList.remove('dragover');slot.ondrop=e=>{e.preventDefault();slot.classList.remove('dragover');combine(e.dataTransfer.getData('text/plain'));};}
 $('finish').disabled=r.accepted.length!==task.target;$('finish').textContent=r.accepted.length===task.target?'点亮本关星星 →':'完成目标后点亮星星';$('stats').textContent=`本关提示 ${r.hints} 次 · 修正 ${r.mistakes} 次 · 最佳 ${state.best[state.current]} 星`;if(r.accepted.length===task.target)$('sceneMessage').textContent='线索齐了，去点亮本关星星吧。';}
function feedback(text,ok){$('panelFeedback').innerHTML=`<div class="feedback ${ok?'':'bad'}">${esc(text)}</div>`;save();}
function crop(item){return `background-image:url('${asset(task.id)}');background-size:450% 450%;background-position:${item.x}% ${item.y}%;`;}
function inspect(id){const item=task.items.find(x=>x.id===id);if(!item)return;X.inspect(state,id);save();const r=run(),collected=r.accepted.includes(id);let actions='';if(collected)actions='<button class="primary" id="returnScene">已收集，继续探索</button>';else if(task.kind==='select')actions='<button id="leave">不符合要求，排除</button><button class="primary" id="collect">符合要求，收集</button>';else if(task.kind==='multi')actions=`<button id="returnScene">继续寻找</button><button class="primary" id="choose">${r.chosen.includes(id)?'移出候选':'加入候选'}</button>`;else actions='<button id="returnScene">再看看卷轴</button><button class="primary" id="putItem">放入当前卷轴</button>';
 modal(`<span class="eyebrow">${esc(task.name)} · ${task.kind==='multi'?'发现一份卷轴':'发现一处线索'}</span><div class="modal-crop" style="${crop(item)}"></div><h2 id="dialogTitle">${esc(item.name)}</h2><p class="note">${esc(item.text)}</p>${task.kind==='combine'?`<p><strong>当前${esc(task.recipes[r.active][0])}：</strong>${esc(task.recipes[r.active][1])}</p>`:`<p><strong>本次委托：</strong>${esc(task.request)}</p>`}<div id="decisionFeedback" role="status"></div><div class="actions">${actions}</div>`);if($('returnScene'))$('returnScene').onclick=()=>{close();renderScene();};if($('collect'))$('collect').onclick=()=>pick(id,true);if($('leave'))$('leave').onclick=()=>pick(id,false);if($('choose'))$('choose').onclick=()=>{const result=X.toggle(state,id);if(!result.ok){$('decisionFeedback').innerHTML=`<div class="feedback bad">${esc(result.message)}</div>`;return;}close();renderScene();toast(r.chosen.includes(id)?'已加入候选，选四份后统一核验。':'已移出候选。');};if($('putItem'))$('putItem').onclick=()=>combine(id,true);}
function pick(id,collect){const result=X.pick(state,id,collect);save();if(!result.ok){$('decisionFeedback').innerHTML=`<div class="feedback bad">${esc(result.message)}<br>可以重新判断，不会扣除已收集的证据。</div>`;renderScene();return;}close();renderScene();toast(result.message);}
function combine(id,fromModal=false){const result=X.combine(state,id);if(fromModal&&!result.ok){$('decisionFeedback').innerHTML=`<div class="feedback bad">${esc(result.message)}</div>`;save();renderScene();return;}if(fromModal)close();feedback(result.message,result.ok);renderScene();toast(result.ok?'卷轴合拢了！线索已收集。':'这件物品还不匹配，看看缺口提示。');}
$('finish').onclick=()=>{const result=X.complete(state,day());if(!result)return;save();totals();showResult(result);};
function showResult(result){modal(`<span class="eyebrow">第 ${state.current+1} 站已点亮 · ${result.final?'全岛通关':'新道路已开启'}</span><h2 id="dialogTitle">${result.final?'星叶群岛，因你而闪耀。':'这一站的发现，已经留下。'}</h2><div class="big-stars">${stars(result.stars)}</div><p>${esc(task.lesson)}</p><div class="feedback">本次 ${result.stars} 星 · 最佳 ${result.best} 星<br>已收藏 ${state.collections.length} / 31 枚知识纪念物 · 累计 ${state.best.reduce((a,b)=>a+b,0)} / 24 星</div><p>${result.stars<3?'想拿三星：不用提示，并把修正控制在一次以内。重玩保留最佳成绩与已有收藏。':'这一关已获得三星。下一站会有不同的风景与玩法。'}</p><p><a class="source" href="${task.url}" target="_blank" rel="noopener">对应学习范围：AWS 官方考试指南 ↗</a></p><div class="actions"><button id="resultMap">回到旅程地图</button><button class="primary" id="resultNext">${state.current===7?'打开通关收藏册':'前往第 '+(state.current+2)+' 站 →'}</button></div><p style="font-size:10px">原创教学示例；组织、场景与金额为虚构设定。不是官方考题。</p>`);$('resultMap').onclick=showMap;$('resultNext').onclick=()=>{close();if(state.current===7)collection();else enter(state.current+1);};}
$('replayLevel').onclick=()=>{modal(`<span class="eyebrow">重新探索本关</span><h2 id="dialogTitle">只重置这一次探索。</h2><p>本关尚未完成的线索、提示和修正次数会清空。已获得的星星、解锁道路和收藏都会保留。</p><div class="actions"><button id="keepProgress">继续当前进度</button><button id="confirmReplay" class="primary">重新探索</button></div>`);$('keepProgress').onclick=close;$('confirmReplay').onclick=()=>enter(state.current,true);};
function collection(){modal(`<span class="eyebrow">星叶群岛 · 个人收藏册</span><h2 id="dialogTitle">沿途的发现，都有回响。</h2><div class="result-metrics"><div><strong>${state.collections.length} / 31</strong><small>知识纪念物</small></div><div><strong>${state.best.reduce((a,b)=>a+b,0)} / 24</strong><small>最佳星星</small></div><div><strong>${state.days.length}</strong><small>完成探索的天数</small></div></div><div class="collection-grid">${badgeNames.flatMap((a,n)=>a.map((name,i)=>`<div class="collection-card ${state.collections.includes(n+':'+i)?'':'locked'}"><span class="stamp">${state.collections.includes(n+':'+i)?'✦':'◇'}</span><strong>${esc(name)}</strong><small>${esc(X.levels[n].name)}${state.collections.includes(n+':'+i)?' · 已收藏':' · 待解锁'}</small></div>`)).join('')}</div><p>${state.best.every(Boolean)?'八站已全部通关，你获得了「星叶群岛探索者」印章。还可以重访每一站，把星星补齐。':'每通过一站，就会留下属于这段旅程的纪念物。重玩不会抹去已经收集的内容。'}</p><p style="font-size:11px">这是当前浏览器中的个人记录。社群排行尚未接入，未展示虚构玩家或分数。</p><div class="actions"><button id="closeCollection" class="primary">合上收藏册，继续旅程</button></div>`,true);$('closeCollection').onclick=close;}
$('collectionButton').onclick=collection;
function help(first=false){modal(`<span class="eyebrow">星叶群岛 · 探索指南</span><h2 id="dialogTitle">每一关，都向前走一点。</h2><div class="guide-step"><b>01</b><div><strong>寻找场景里的真实小物件</strong>点击书、信件、卷轴或仪器查看线索。用「＋」放大，拖动画面探索边角；找不到可以提示一片区域。</div></div><div class="guide-step"><b>02</b><div><strong>三种关卡，三种解法</strong>筛选关逐件判断；卷轴关从十份中选四份再核验；组合关先读卷轴，把对应物件拖入缺口，也可点开后选择放入。</div></div><div class="guide-step"><b>03</b><div><strong>点亮星星，解锁下一站</strong>集齐目标后点击「点亮本关星星」。通关一星、不用提示一星、修正不超过一次再得一星。星星和收藏自动保存。</div></div><p class="note">没有倒计时。选错可以读解释再试；重玩只重置本关，保留你的最佳星级与收藏。</p><div class="actions"><button id="startGuide" class="primary">${first?'明白了，开始找线索':'继续我的旅程'}</button></div>`);$('startGuide').onclick=()=>{state.guide=true;save();close();};}
$('help').onclick=()=>help();
function bounds(){const w=$('viewport').clientWidth,h=$('viewport').clientHeight;panX=Math.max(w*(1-zoom),Math.min(0,panX));panY=Math.max(h*(1-zoom),Math.min(0,panY));$('world').style.transform=`translate(${panX}px,${panY}px) scale(${zoom})`;$('viewport').classList.toggle('zoomed',zoom>1);$('zoomLabel').textContent=`${zoom===1?'全景':'细节'} · ${Math.round(zoom*100)}%`;$('zoomOut').disabled=zoom===1;$('zoomIn').disabled=zoom===4;}
function setZoom(n){n=Math.max(1,Math.min(4,n));const w=$('viewport').clientWidth,h=$('viewport').clientHeight;panX=w/2-(w/2-panX)*n/zoom;panY=h/2-(h/2-panY)*n/zoom;zoom=n;bounds();}
function resetView(){zoom=1;panX=panY=0;clearTimeout(hintTimer);$('hintRegion').hidden=true;bounds();}
$('zoomIn').onclick=()=>setZoom(zoom+.5);$('zoomOut').onclick=()=>setZoom(zoom-.5);$('resetView').onclick=resetView;
$('hint').onclick=()=>{const r=run();let candidate;if(task.kind==='combine')candidate=task.items.find(x=>x.tag===task.recipes[r.active][2]&&!r.accepted.includes(x.id));else candidate=task.items.find(x=>x.valid&&!r.accepted.includes(x.id)&&!(task.kind==='multi'&&r.chosen.includes(x.id)));if(!candidate){toast('目标已经齐了，可以核验或点亮星星。');return;}resetView();r.hints++;const h=$('hintRegion');h.hidden=false;h.style.left=Math.max(0,Math.min(77,candidate.x-11.5))+'%';h.style.top=Math.max(0,Math.min(72,candidate.y-14))+'%';hintTimer=setTimeout(()=>h.hidden=true,7000);renderPanel();save();toast('这片区域里，有一处本次需要的线索。');};
const viewport=$('viewport');viewport.addEventListener('pointerdown',e=>{if(zoom===1||e.button!==0)return;if(task?.kind==='combine'&&e.pointerType==='mouse'&&e.target.closest?.('[draggable="true"]'))return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,px:panX,py:panY,moved:false};});viewport.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>7){drag.moved=true;viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging');}if(drag.moved){panX=drag.px+dx;panY=drag.py+dy;bounds();}});function endDrag(){if(drag?.moved)suppressUntil=Date.now()+250;drag=null;viewport.classList.remove('dragging');}viewport.addEventListener('pointerup',endDrag);viewport.addEventListener('pointercancel',endDrag);viewport.addEventListener('keydown',e=>{if(e.target!==viewport)return;if(e.key==='+'||e.key==='='){setZoom(zoom+.5);e.preventDefault();}else if(e.key==='-'){setZoom(zoom-.5);e.preventDefault();}else if(e.key==='0')resetView();else if(zoom>1&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();panX+=e.key==='ArrowLeft'?60:e.key==='ArrowRight'?-60:0;panY+=e.key==='ArrowUp'?60:e.key==='ArrowDown'?-60:0;bounds();}});
async function exitImmersive(){if(document.fullscreenElement)await document.exitFullscreen?.();$('sceneWrap').classList.remove('expanded');$('fullscreen').textContent='沉浸查看';}
$('fullscreen').onclick=async()=>{if(document.fullscreenElement){await document.exitFullscreen();return;}if($('sceneWrap').classList.contains('expanded')){exitImmersive();bounds();return;}try{if($('sceneWrap').requestFullscreen)await $('sceneWrap').requestFullscreen();else throw Error();}catch{$('sceneWrap').classList.add('expanded');$('fullscreen').textContent='退出沉浸';bounds();}};document.addEventListener('fullscreenchange',()=>{$('fullscreen').textContent=document.fullscreenElement?'退出沉浸':'沉浸查看';bounds();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.fullscreenElement){$('sceneWrap').classList.remove('expanded');$('fullscreen').textContent='沉浸查看';bounds();}});window.addEventListener('resize',()=>{bounds();positionNodes();});$('art').onerror=()=>{$('sceneMessage').textContent='场景加载失败，请刷新后重试。';};renderMap();
